package main

import (
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type OrderRec struct {
	OrId    string // PIC X(5) @0 len=5
	OrStat  string // PIC X(1) @5 len=1
	OrQty   int64  // PIC 9(3) @6 len=3
	OrPrice decimal.Decimal
}

var WsEofFlag string // PIC X len=1 = "N"
var WsTotal decimal.Decimal
var WsGrand decimal.Decimal
var WsNewCount int64
var WsShipCount int64
var WsCancelCount int64
var WsInvalid int64
var WsBadQty int64
var WsQtyEd string
var WsPriceEd string
var WsTotalEd string
var WsGrandEd string

var OrderRecVar OrderRec

var inputDone bool
var records []string
var recIdx int

func isInputDone() bool { return inputDone }

func formatCount2(v int64) string {
	m := v % 100
	if m < 0 {
		m += 100
	}
	return fmt.Sprintf("%02d", m)
}

func truncStore(val decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	t := val.Truncate(scale)
	// keep low-order digits: modulo 10^(intDigits+scale) on scaled integer
	totalDigits := intDigits + int(scale)
	mod := decimal.New(1, int32(totalDigits)) // 10^totalDigits
	scaled := t.Shift(scale) // integer
	// truncate toward zero already; compute scaled truncated to integer
	scaled = scaled.Truncate(0)
	neg := scaled.IsNegative()
	a := scaled.Abs()
	// a mod mod
	q := a.QuoRem(mod, mod) // not good; use DivMod?
	// Use Mod
	m := a.Mod(mod)
	if neg && !m.IsZero() {
		m = m.Neg()
	}
	return m.Shift(-scale)
}

func storeTotal(v decimal.Decimal) {
	WsTotal = truncStore(v, 8, 2)
}
func storeGrand(v decimal.Decimal) {
	WsGrand = truncStore(v, 10, 2)
}

func formatEdited(pic string, val decimal.Decimal) string {
	var intPic, fracPic string
	if idx := strings.Index(pic, "."); idx >= 0 {
		intPic = pic[:idx]
		fracPic = pic[idx+1:]
	} else {
		intPic = pic
		fracPic = ""
	}
	fracLen := len(fracPic)
	// count digit placeholders
	intCap := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intCap++
		}
	}
	t := val.Abs().Truncate(int32(fracLen))
	scaled := t.Shift(int32(fracLen)).Truncate(0)
	s := scaled.String()
	// scaled String may contain decimal point if fracLen? No, shifted to integer.
	// Remove possible minus (abs so no) and decimal point
	if idx := strings.Index(s, "."); idx >= 0 {
		s = s[:idx]
	}
	if s == "" {
		s = "0"
	}
	// ensure at least fracLen+1 digits
	for len(s) < fracLen+1 {
		s = "0" + s
	}
	var fracStr string
	var intFull string
	if fracLen > 0 {
		fracStr = s[len(s)-fracLen:]
		intFull = s[:len(s)-fracLen]
	} else {
		fracStr = ""
		intFull = s
	}
	// keep low order / pad
	var intStr string
	if len(intFull) > intCap {
		intStr = intFull[len(intFull)-intCap:]
	} else {
		intStr = strings.Repeat("0", intCap-len(intFull)) + intFull
	}
	// first significant index
	firstSig := intCap - 1
	for i := 0; i < intCap; i++ {
		if intStr[i] != '0' {
			firstSig = i
			break
		}
	}
	var b strings.Builder
	digitIdx := 0
	for _, ch := range intPic {
		switch ch {
		case 'Z':
			if digitIdx < firstSig {
				b.WriteByte(' ')
			} else {
				b.WriteByte(intStr[digitIdx])
			}
			digitIdx++
		case '9':
			b.WriteByte(intStr[digitIdx])
			digitIdx++
		case ',':
			if digitIdx <= firstSig {
				// check: if firstSig >= digitIdx => all left digits zero => space
				// edge: when value is zero firstSig is last index, so commas before last => space
				b.WriteByte(' ')
			} else {
				b.WriteByte(',')
			}
		case '.':
			b.WriteByte('.')
		default:
			b.WriteByte(byte(ch))
		}
	}
	if fracLen > 0 {
		b.WriteByte('.')
		b.WriteString(fracStr)
	}
	return b.String()
}

func parseQty(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	var v int64
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			v = v*10 + int64(ch-'0')
		}
	}
	// keep low 3 digits? field is exactly 3 digits; but mod 1000 in case
	v = v % 1000
	return v
}

func parsePrice(s string) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.Zero
	}
	var v int64
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			v = v*10 + int64(ch-'0')
		}
	}
	// keep low 6 digits
	v = v % 1000000
	return decimal.New(v, -2)
}

func loadRecords() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		// if no file, treat as empty?
		records = nil
		return
	}
	// split on \n
	raw := strings.Split(string(data), "\n")
	records = nil
	for i, line := range raw {
		// detect trailing newline causing extra empty element
		if i == len(raw)-1 {
			// last piece after final \n
			if len(raw) > 1 || line != "" {
				// if original ended with \n, last line is "" -> skip
				if line == "" {
					continue
				}
			} else {
				// single empty -> no records
				continue
			}
		}
		// strip trailing \r
		if strings.HasSuffix(line, "\r") {
			line = line[:len(line)-1]
		}
		records = append(records, line)
	}
}

func setRecord(line string) {
	// pad/truncate to 15 bytes
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	OrderRecVar.OrId = line[0:5]
	OrderRecVar.OrStat = line[5:6]
	OrderRecVar.OrQty = parseQty(line[6:9])
	OrderRecVar.OrPrice = parsePrice(line[9:15])
}

func MainPara() {
	// OPEN INPUT ORDER-FILE
	loadRecords()
	recIdx = 0
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	// CLOSE ORDER-FILE
	SummaryPara()
}

func ReadPara() {
	if recIdx < len(records) {
		setRecord(records[recIdx])
		recIdx++
	} else {
		inputDone = true
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	storeTotal(decimal.Zero)
	// EVALUATE TRUE
	if OrderRecVar.OrQty == 0 {
		WsBadQty = (WsBadQty + 1) % 100
		fmt.Printf("%s BAD QTY\n", OrderRecVar.OrId)
	} else if OrderRecVar.OrStat == "N" {
		// COMPUTE WS-TOTAL = OR-QTY * OR-PRICE (truncated)
		q := decimal.New(OrderRecVar.OrQty, 0)
		v := q.Mul(OrderRecVar.OrPrice).Truncate(2)
		storeTotal(v)
		WsNewCount = (WsNewCount + 1) % 100
		ShowPara()
	} else if OrderRecVar.OrStat == "S" {
		q := decimal.New(OrderRecVar.OrQty, 0)
		factor := decimal.New(105, -2)
		v := q.Mul(OrderRecVar.OrPrice).Mul(factor).Round(2)
		storeTotal(v)
		WsShipCount = (WsShipCount + 1) % 100
		ShowPara()
	} else if OrderRecVar.OrStat == "C" {
		WsCancelCount = (WsCancelCount + 1) % 100
		ShowPara()
	} else {
		WsInvalid = (WsInvalid + 1) % 100
		fmt.Printf("%s BAD STATUS %s\n", OrderRecVar.OrId, OrderRecVar.OrStat)
	}
	// ADD WS-TOTAL TO WS-GRAND
	storeGrand(WsGrand.Add(WsTotal))
	ReadPara()
}

func ShowPara() {
	WsQtyEd = formatEdited("ZZ9", decimal.New(OrderRecVar.OrQty, 0))
	WsPriceEd = formatEdited("Z,ZZ9.99", OrderRecVar.OrPrice)
	WsTotalEd = formatEdited("ZZ,ZZZ,ZZ9.99", WsTotal)
	fmt.Printf("%s %s %s %s %s\n", OrderRecVar.OrId, OrderRecVar.OrStat, WsQtyEd, WsPriceEd, WsTotalEd)
}

func SummaryPara() {
	WsGrandEd = formatEdited("Z,ZZZ,ZZZ,ZZ9.99", WsGrand)
	fmt.Printf("NEW: %s SHIPPED: %s CANCELLED: %s\n", formatCount2(WsNewCount), formatCount2(WsShipCount), formatCount2(WsCancelCount))
	fmt.Printf("INVALID: %s BAD QTY: %s\n", formatCount2(WsInvalid), formatCount2(WsBadQty))
	fmt.Printf("GRAND TOTAL: %s\n", WsGrandEd)
}

func main() {
	WsEofFlag = "N"
	WsTotal = decimal.Zero
	WsGrand = decimal.Zero
	WsNewCount = 0
	WsShipCount = 0
	WsCancelCount = 0
	WsInvalid = 0
	WsBadQty = 0
	inputDone = false
	MainPara()
}

